import backtrader as bt


class IntradayTrendStrategy(bt.Strategy):
    params = (
        ('p_smooth', 20),
        ('p_boll', 20),
        ('devfactor', 2.0),
        ('p_atr', 14),
        ('atr_mult', 2.0),
    )

    def __init__(self):
        self.ema = bt.indicators.EMA(self.data.close, period=self.p.p_smooth)
        self.boll = bt.indicators.BollingerBands(
            self.data.close,
            period=self.p.p_boll,
            devfactor=self.p.devfactor
        )
        self.atr = bt.indicators.ATR(self.data, period=self.p.p_atr)

        self.order = None
        self.stop_order = None

    def notify_order(self, order):
        if order.status in [order.Submitted, order.Accepted]:
            return

        if order.status in [order.Completed]:
            if order == self.order:
                if self.position:
                    stop_distance = self.atr[0] * self.p.atr_mult
                    if self.position.size > 0:
                        stop_price = order.executed.price - stop_distance
                        self.stop_order = self.sell(exectype=bt.Order.Stop, price=stop_price)
                    elif self.position.size < 0:
                        stop_price = order.executed.price + stop_distance
                        self.stop_order = self.buy(exectype=bt.Order.Stop, price=stop_price)
                else:
                    if self.stop_order:
                        self.cancel(self.stop_order)
                        self.stop_order = None
                self.order = None
            elif order == self.stop_order:
                self.stop_order = None

        elif order.status in [order.Canceled, order.Margin, order.Rejected]:
            if order == self.order:
                self.order = None
            if order == self.stop_order:
                self.stop_order = None

    def next(self):
        if self.order:
            return

        long_signal = (
            self.data.close[-1] < self.boll.bot[-1] and
            self.data.close[0] > self.boll.bot[0] and
            self.data.close[0] > self.ema[0]
        )

        short_signal = (
            self.data.close[-1] > self.boll.top[-1] and
            self.data.close[0] < self.boll.top[0] and
            self.data.close[0] < self.ema[0]
        )

        if not self.position:
            if long_signal:
                self.order = self.buy()
            elif short_signal:
                self.order = self.sell()
        else:
            if self.position.size > 0 and short_signal:
                if self.stop_order:
                    self.cancel(self.stop_order)
                    self.stop_order = None
                self.order = self.close()
            elif self.position.size < 0 and long_signal:
                if self.stop_order:
                    self.cancel(self.stop_order)
                    self.stop_order = None
                self.order = self.close()
